import{d as c,C as t,o as u,c as p,j as a,a as r,E as o,a3 as m}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第三十五章","description":"从执大象与往而不害，到道之淡而有用，辨一时感悦与不可穷尽的作用。","frontmatter":{"title":"道德经第三十五章","description":"从执大象与往而不害，到道之淡而有用，辨一时感悦与不可穷尽的作用。","category":"guide","aliases":["道德经第三十五章","老子第三十五章","dao de jing chapter 35"],"source":["王弼《道德真经注》卷二"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-35.md","filePath":"daoism/dao-de-jing/chapter-35.md","lastUpdated":1794189804000}'),b={name:"daoism/dao-de-jing/chapter-35.md"},y=c({...b,setup(g){const n=[{id:"holding-the-great-image",label:"执大象，天下往",showLabel:!0,sentences:[[{text:"执",glossary:"zhi"},{text:"大象",glossary:"daxiang"},"，天下往。"]],note:["【白话】持守大道之象，天下便归往于此。这里的大象是对道的称述，不是一件具体可见、可供占有的巨大物象。","【王弼注择要】「大象，天象之母也。」注又说「能包统万物，无所犯伤」，并以「主若执之，则天下往也」说明在上者执守的方向。","【读法】执在此取持守义，与第二十九章固执占持分开。大象不能直接当成体型大的动物，也不直接等同于易经的某个卦象。"]},{id:"approaching-without-harm",label:"往而不害，安平太",showLabel:!0,sentences:[["往而不害，安平",{text:"太",glossary:"tai"},"。"]],note:["【白话】归往而不受伤害，于是安宁、平和、通泰。前一句所说天下归往，随即由不害限定其条件与结果。","【王弼注择要】「无形无识，不徧不彰，故万物得往而不害妨也。」王弼用不偏、不显彰说明能够容纳万物，使其归往而不被伤害妨碍。","【读法】太本页按通泰、安泰理解，所据录文作大。天下往不能脱离不害读作招揽控制天下的技巧；无识等字在此也不宜直接套入现代认知障碍的意思。"]},{id:"music-and-food-attract-travelers",label:"乐与饵，过客止",showLabel:!0,sentences:[[{text:"乐",glossary:"yue"},"与",{text:"饵",glossary:"er"},"，过客止。"]],note:["【白话】音乐与美食，能使路过的人停下脚步。这里举出可直接悦耳适口、吸引人的事物，为下文道的平淡作对照。","【王弼注择要】「乐与饵应时感悦人心也」，又说「乐与饵则能令过客止」。注指出这种感悦来得直接，能促成一时驻足。","【读法】乐读 yuè，指音乐；饵指食物、美食，不在这里按诱骗的饵料理解。本章借感悦作对照，并未要求一概拒绝音乐与饮食。"]},{id:"plain-speech-and-inexhaustible-use",label:"用之不足既",showLabel:!0,sentences:[["道之",{text:"出口",glossary:"chukou"},"，淡乎其无味，视之不足见，听之不足闻，用之不足",{text:"既",glossary:"ji"},"。"]],note:["【白话】道表达为言说，淡泊得仿佛没有滋味；看它，不足以悦目，听它，不足以娱耳，然而运用起来却不能穷尽。它的价值不只由第一眼、第一耳的感受衡量。","【王弼注择要】「道之出言淡然无味」，又分别说「不足以悦其目」「不足以娱其耳」，最后说「用之不可穷极也」。本页据此将视听之淡与作用之不尽对读。","【读法】出口依出言理解；既作尽。不足见、不足闻既连道之难由感官把握，也循本段王注说明不以悦目娱耳见长，不把不足既误译成不值得使用。"]}],i=[{id:"zhi",term:"执",sense:2},{id:"daxiang",term:"大象",sense:1},{id:"tai",term:"太",sense:1},{id:"yue",term:"乐",sense:2,pinyin:"yuè"},{id:"er",term:"饵",sense:1},{id:"chukou",term:"出口",sense:1},{id:"ji",term:"既",sense:1}];return(x,e)=>{const s=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return u(),p("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第三十五章",tabindex:"-1"},[r("道德经第三十五章 "),a("a",{class:"header-anchor",href:"#道德经第三十五章","aria-label":'Permalink to "道德经第三十五章"'},"​")],-1)),o(s,{title:"道的言说平淡，为什么用之不尽",summary:"本章先说执大象可以使天下归往而不受伤害，再以音乐、美食使过客停步为对照。道的言说虽淡、难以悦耳娱目，其作用却不能穷尽。",points:[{label:"先读",text:"大象在这里连道理解，归往的前提是往而不害、安平太。"},{label:"再辨",text:"乐与饵使人一时停步，用来衬出道的言说不以感官吸引见长。"},{label:"后看",text:"无味、难见难闻与用之不足既对照，落点在作用不可穷尽。"}],hint:"乐与饵的乐读 yuè，与第三十一章乐杀人的 lè 分义；既在本章取尽义，太按通泰理解。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[r("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),o(l,{sections:n,glossary:i}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[r("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),o(d,{lines:[{text:"往而不害，安平太。",tone:"归往应以不害为前提",guide:"看归往的结果是否使人安宁通泰，而不只看聚集了多少人。"},{text:"乐与饵，过客止。",tone:"感悦使人暂驻",guide:"理解音乐、美食的直接吸引，再与道的平淡和长久作用对读。"},{text:"道之出口，淡乎其无味，视之不足见，听之不足闻，用之不足既。",tone:"平淡而作用不尽",guide:"不凭热闹与新鲜感判断全部价值，也不把平淡本身当作正确的保证。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[r("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),o(h,{items:i}),e[4]||(e[4]=m('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-为什么在执大象之后突然写乐与饵" tabindex="-1">象：为什么在执大象之后突然写乐与饵？ <a class="header-anchor" href="#象-为什么在执大象之后突然写乐与饵" aria-label="Permalink to &quot;象：为什么在执大象之后突然写乐与饵？&quot;">​</a></h3><p>天下归往与过客停步都写人有所趋向，但所凭不同：前者连不害与安平太，后者连直接的感官愉悦。这一对照引出末段，说明道的平淡仍可以有深远作用。</p><h3 id="理-淡乎其无味-是否表示越乏味越接近道" tabindex="-1">理：淡乎其无味，是否表示越乏味越接近道？ <a class="header-anchor" href="#理-淡乎其无味-是否表示越乏味越接近道" aria-label="Permalink to &quot;理：淡乎其无味，是否表示越乏味越接近道？&quot;">​</a></h3><p>本章以用之不足既收束，平淡要与实际的成全作用一起看。若只有晦涩、枯燥而不能使人受益，就不能借无味自证深刻；感官吸引也不能替代对作用的检验。</p><h3 id="用-今天如何分辨吸引力与持续价值" tabindex="-1">用：今天如何分辨吸引力与持续价值？ <a class="header-anchor" href="#用-今天如何分辨吸引力与持续价值" aria-label="Permalink to &quot;用：今天如何分辨吸引力与持续价值？&quot;">​</a></h3><p>可以先享受作品、产品或表达带来的直接感悦，再观察它在持续使用中是否有益、是否伤人、是否能帮助理解与行动。两种价值可以并存，不须以排斥乐与饵来证明自己。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>给平淡的事物一点时间。</strong> 学习一项基础方法或养成习惯时，除了初始兴趣，也看长期是否减少困惑、提高理解与行动能力。时间可以帮助检验价值，但不能替代实际效果。</p><p><strong>检视吸引之后发生了什么。</strong> 设计阅读、教学或协作入口时，吸引人停步只是起点；接下来应让人安稳进入、得到帮助，避免以不断刺激维持依赖。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：我最近被什么吸引而停下？其中哪些只有片刻感悦，哪些在反复使用后仍能帮助自己、也不损害他人？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>本站保留「安平太」，所据 HFL 录文作「安平大」；本页太取通泰、安泰义，不与已有泰字的过度义混用。</li><li>大象循王弼天象之母、包统万物的注解；执另列执守义。乐的音乐义读 yuè，与乐于义分开；饵取食物义，既取尽义。</li><li>末段依王弼出言、悦目娱耳与用之不可穷极的解释，不用无味为难懂或无用辩护。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_002.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷二 HFL 本电子录文，011a–011b</a>。</p>',15))])}}});export{_ as __pageData,y as default};
